import Foundation
import Testing
@testable import NativeContentState
import NodysseyNativeCore

/// Receipts/snapshots are generated by reaction-repository-regression.py from the actual
/// OfflineFirstPostRepository and Room, not invented here. Separate-process contract replay,
/// not an in-process Kotlin/Native linkage test.
@Test(.enabled(if: ProcessInfo.processInfo.environment["CONTENT_REPOSITORY_REPLAY"] != nil),
      arguments: [false, true]) @MainActor
func actualRepositoryFallbackAndMergedWindowsKeepCommandBlocked(_ opening: Bool) async throws {
    let path = try #require(ProcessInfo.processInfo.environment["CONTENT_REPOSITORY_REPLAY"])
    let replay = try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: URL(fileURLWithPath: path)))
    let app = ScriptedContentContext()
    let command = ContentThreadCommand()
    let affected: Int64 = opening ? 6 : 7
    app.respond = { _, _ in throw NativeFailure(code: "NETWORK", message: "Fixture response lost") }
    await command.react(app, postID: 42, commentID: affected, action: "ChickenLeg", page: 1, opening: opening)?.value
    for (key, page, extend) in [("offlineSnapshot", Int64(1), false), ("mergedSnapshot", Int64(2), true), ("replacementSnapshot", Int64(2), false)] {
        let snapshot = try #require(replay[key])
        app.respond = { operation, _ in
            #expect(operation == "thread.load")
            return snapshot
        }
        await command.loadThread(app, postID: 42, page: page, extend: extend)
        #expect(command.reactionsBlocked, "Actual repository \(key) must not reconcile")
    }
    #expect(command.reactionsBlocked)
    #expect(app.calls.filter { $0.0 == "thread.react" }.count == 1)
}

@Test(.enabled(if: ProcessInfo.processInfo.environment["CONTENT_REPOSITORY_COMPLETE"] == "1"),
      arguments: [false, true]) @MainActor
func actualRepositoryNetworkCoverageReconcilesOnlyMatchingIdentity(_ opening: Bool) async throws {
    let path = try #require(ProcessInfo.processInfo.environment["CONTENT_REPOSITORY_REPLAY"])
    let replay = try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: URL(fileURLWithPath: path)))
    let app = ScriptedContentContext()
    let command = ContentThreadCommand()
    let affected: Int64 = opening ? 6 : 7
    app.respond = { _, _ in throw NativeFailure(code: "NETWORK", message: "Fixture response lost") }
    await command.react(app, postID: 42, commentID: affected, action: "ChickenLeg", page: 1, opening: opening)?.value
    #expect(replay["offlineReadError"]?.string == "NETWORK")
    app.respond = { _, _ in throw NativeFailure(code: "NETWORK", message: "Repository network read refused fallback") }
    await command.reconcileReactions(app, postID: 42)
    #expect(command.reactionsBlocked)
    for key in ["otherPageReceipt", "missingConfigReceipt"] {
        let receipt = try #require(replay[key])
        app.respond = { _, _ in receipt }
        await command.reconcileReactions(app, postID: 42)
        #expect(command.reactionsBlocked)
    }
    let receipt = try #require(replay["relevantReceipt"])
    app.respond = { _, _ in receipt }
    await command.reconcileReactions(app, postID: 42)
    #expect(!command.reactionsBlocked)
    #expect(app.calls.filter { $0.0 == "thread.react" }.count == 1)
}
